<?php $mode=$mode==='login'?'login':$mode; $heading=['login'=>'Welcome back.','register'=>'Your WIKI story starts here.','forgot-password'=>'A fresh start.','reset-password'=>'Choose a new password.'][$mode]; $action=['login'=>'login','register'=>'register','forgot-password'=>'forgot','reset-password'=>'reset'][$mode]; ?>
<section class="auth-shell"><div class="auth-image"><img src="/assets/images/collection.jpg" alt="WIKI editorial collection" width="900" height="1100"><div><p class="eyebrow">DISTINCTLY YOU.</p><h2>Good things<br>start here.</h2></div></div><div class="auth-form"><p class="eyebrow">YOUR WIKI ACCOUNT</p><h1><?=e($heading)?></h1><form method="post" action="<?=e($path)?>"><?=csrf_field()?><input type="hidden" name="action" value="<?=e($action)?>"><?php if($mode==='register'): ?><label>Your name<input name="name" autocomplete="name" maxlength="120" required></label><?php endif ?><?php if($mode!=='reset-password'): ?><label>Email address<input type="email" name="email" autocomplete="email" maxlength="190" required></label><?php else: ?><input type="hidden" name="token" value="<?=e($_GET['token']??'')?>"><?php endif ?><?php if($mode!=='forgot-password'): ?><label>Password<input type="password" name="password" autocomplete="<?=$mode==='login'?'current-password':'new-password'?>" minlength="<?=$mode==='login'?1:12?>" maxlength="200" required></label><?php if($mode!=='login'): ?><p class="muted">Use at least 12 characters. A unique passphrase works well.</p><?php endif ?><?php endif ?><button class="btn full"><?=e(['login'=>'Sign in','register'=>'Create account','forgot-password'=>'Send reset link','reset-password'=>'Update password'][$mode])?> ↗</button></form><?php if($mode==='login'): ?><a class="underlined" href="/forgot-password">Forgot your password?</a><p>New to WIKI? <a class="underlined" href="/register">Create an account</a></p><?php else: ?><p>Already have an account? <a class="underlined" href="/login">Sign in</a></p><?php endif ?></div></section>
